from __future__ import annotationsimport argparseimport configparserimport csvimport globimport jsonimport osimport reimport shutilimport timeimport warningsimport zipfilefrom dataclasses import dataclassfrom io import BytesIO, StringIOfrom pathlib import Pathfrom typing import Optionalfrom urllib.parse import quote, urlparseimport numpy as npimport pandas as pdimport pyvoimport requestsfrom astropy.io import fitsfrom astropy.io.fits.verify import VerifyWarningfrom astropy.table import Tablefrom tqdm import tqdm# ============================================================# GLOBAL CONFIG# ============================================================DEFAULT_TARGETS_CSV = "/Users/astro502/Chemists/ASTR502_Master_Target_List.csv"          # master list you use for KOA/ExoFOP/CSVDEFAULT_ESO_TARGETS_CSV = "/Users/astro502/Chemists/ASTR502_Mega_Target_List.csv"        # ESO script currently points to thisDEFAULT_MATCHED_CSV = "matched_targets.csv"                     # SOPHIE name list csv (archive_name)DATA_DIR = Path("data")OUT_ORGANIZED = DATA_DIR / "organized_spectra"OUT_ORGANIZED.mkdir(parents=True, exist_ok=True)# Archive roots (kept as-is / close to your scripts)ESO_OUTDIR = DATA_DIR / "raw" / "ESO"EXOFOP_DIR = DATA_DIR / "exofop_spectra"KOA_DATA_ROOT = DATA_DIR / "koa"KOA_META_ROOT = Path("metadata") / "koa"SOPHIE_OUTDIR = DATA_DIR / "sophie"FITS_EXTENSIONS = (".fits", ".fits.gz", ".fit")# ============================================================# --------------------- ESO DOWNLOAD --------------------------# ============================================================def eso_clean(s):    return re.sub(r"[^A-Za-z0-9._-]+", "_", str(s))def eso_dl_table(datalink_url: str, timeout_sec: int):    r = requests.get(datalink_url, timeout=timeout_sec)    r.raise_for_status()    return Table.read(BytesIO(r.content), format="votable")def eso_pick_main_urls(t: Table):    if "access_url" not in t.colnames:        return []    if "semantics" in t.colnames:        urls = [            str(t["access_url"][i])            for i in range(len(t))            if t["access_url"][i] is not None and "#this" in str(t["semantics"][i])        ]        if urls:            return urls    urls = [str(u) for u in t["access_url"] if u is not None]    fitsy = [u for u in urls if "fits" in u.lower()]    return fitsy if fitsy else urls[:1]def eso_download(url: str, path: str):    if os.path.exists(path) and os.path.getsize(path) > 0:        return False    r = requests.get(url, stream=True, timeout=120)    r.raise_for_status()    with open(path, "wb") as f:        for chunk in r.iter_content(1024 * 1024):            if chunk:                f.write(chunk)    return Truedef run_eso_download(    csv_file: str,    outdir: Path,    max_targets: int,    max_files_per_target: int,    radius_arcmin: float,    timeout_sec: int,):    outdir = Path(outdir)    outdir.mkdir(parents=True, exist_ok=True)    tap = pyvo.dal.TAPService("https://archive.eso.org/tap_obs")    df = pd.read_csv(csv_file)    if max_targets > 0:        df = df.head(max_targets)    inst_like = ["%HARPS%", "%UVES%", "%ESPRESSO%", "%FEROS%"]    inst_clause = " OR ".join([f"instrument_name LIKE '{s}'" for s in inst_like])    radius_deg = radius_arcmin / 60.0    for _, row in df.iterrows():        name = eso_clean(row.get("pl_name", row.get("hostname", "target")))        ra = float(row["ra"])        dec = float(row["dec"])        target_dir = outdir / name        target_dir.mkdir(parents=True, exist_ok=True)        adql = f"""        SELECT TOP 200 instrument_name, access_url, access_format        FROM ivoa.ObsCore        WHERE dataproduct_type='spectrum'          AND 1=CONTAINS(POINT('ICRS', s_ra, s_dec), CIRCLE('ICRS', {ra}, {dec}, {radius_deg}))          AND ({inst_clause})        """        res = tap.search(adql).to_table()        print(f"\n[ESO] {name}: {len(res)} ESO spectra rows")        if len(res) == 0:            continue        got = 0        for dl in tqdm(list(res["access_url"]), total=len(res), desc=f"ESO {name}", leave=False):            if got >= max_files_per_target:                break            try:                t = eso_dl_table(str(dl), timeout_sec=timeout_sec)                urls = eso_pick_main_urls(t)            except Exception:                continue            for u in urls:                if got >= max_files_per_target:                    break                fn = os.path.basename(urlparse(u).path) or eso_clean(u)                path = target_dir / fn                try:                    if eso_download(u, str(path)):                        got += 1                except Exception:                    continue        print(f"[ESO] {name}: downloaded {got} file(s)")# ============================================================# --------------------- EXOFOP DOWNLOAD -----------------------# ============================================================CONNECT_TIMEOUT = 20READ_TIMEOUT = 300HEADERS = {"User-Agent": "Mozilla/5.0 (ASTR502 script)"}SESSION = requests.Session()SESSION.headers.update(HEADERS)def exofop_get_with_retries(url, stream=False, retries=4, backoff=10):    for attempt in range(1, retries + 1):        try:            return SESSION.get(url, stream=stream, timeout=(CONNECT_TIMEOUT, READ_TIMEOUT))        except requests.exceptions.ReadTimeout:            print(f"[WARN] timeout (attempt {attempt}/{retries}) for {url}")        except requests.exceptions.ConnectionError:            print(f"[WARN] connection error (attempt {attempt}/{retries}) for {url}")        if attempt < retries:            time.sleep(backoff * attempt)    return Nonedef exofop_gototicid(target_name: str) -> str | None:    url = f"https://exofop.ipac.caltech.edu/tess/gototicid.php?target={quote(target_name)}&json"    r = exofop_get_with_retries(url, stream=False)    if r is None:        return None    r.raise_for_status()    data = r.json()    if data.get("status") != "OK":        return None    tic = data.get("TIC")    if tic is None:        return None    return str(tic).strip()def exofop_download_filelist(tic: str) -> pd.DataFrame | None:    url = f"https://exofop.ipac.caltech.edu/tess/download_filelist.php?id={tic}&output=csv"    r = exofop_get_with_retries(url, stream=False)    if r is None:        return None    r.raise_for_status()    text = r.text.strip()    if not text or "ERROR" in text[:200].upper():        return None    df = pd.read_csv(StringIO(text))    df.columns = [c.strip() for c in df.columns]    return dfdef exofop_download_all_files_zip(tic: str, out_zip: Path) -> bool:    url = f"https://exofop.ipac.caltech.edu/tess/download_files_zip.php?id={tic}"    r = exofop_get_with_retries(url, stream=True)    if r is None:        return False    if r.status_code != 200:        return False    out_zip.parent.mkdir(parents=True, exist_ok=True)    try:        with r:            with open(out_zip, "wb") as f:                for chunk in r.iter_content(chunk_size=1024 * 256):                    if chunk:                        f.write(chunk)    except requests.exceptions.ReadTimeout:        try:            if out_zip.exists():                out_zip.unlink()        except OSError:            pass        return False    return out_zip.exists() and out_zip.stat().st_size > 0def exofop_extract_zip(zip_path: Path, out_dir: Path) -> None:    out_dir.mkdir(parents=True, exist_ok=True)    with zipfile.ZipFile(zip_path, "r") as z:        z.extractall(out_dir)def exofop_keep_only_selected_files(folder: Path, allowed_names: set[str]) -> int:    kept = 0    for p in folder.rglob("*"):        if p.is_file():            if p.name in allowed_names:                kept += 1            else:                p.unlink()    for p in sorted(folder.rglob("*"), reverse=True):        if p.is_dir():            try:                p.rmdir()            except OSError:                pass    return keptdef run_exofop_download(target_list_csv: str, out_root: Path, max_targets: int):    out_root.mkdir(parents=True, exist_ok=True)    targets = pd.read_csv(target_list_csv)    if max_targets > 0:        targets = targets.head(max_targets)    name_cols = [c for c in ["hostname", "pl_name"] if c in targets.columns]    if not name_cols:        raise ValueError(f"No hostname or pl_name columns found in {target_list_csv}.")    tic_cache: dict[str, Optional[str]] = {}    for _, row in targets.iterrows():        target_name = None        for c in name_cols:            val = row.get(c)            if isinstance(val, str) and val.strip():                target_name = val.strip()                break        if not target_name:            continue        tic = tic_cache.get(target_name)        if tic is None:            tic = exofop_gototicid(target_name)            tic_cache[target_name] = tic        if tic is None:            print(f"[ExoFOP NONE] {target_name}: no TIC match in ExoFOP.")            continue        filelist = exofop_download_filelist(tic)        if filelist is None or filelist.empty:            print(f"[ExoFOP NONE] TIC {tic}: no files or unexpected filelist format.")            continue        type_col = "Type" if "Type" in filelist.columns else None        name_col = "File Name" if "File Name" in filelist.columns else None        if type_col is None or name_col is None:            print(f"[ExoFOP NONE] TIC {tic}: filelist missing Type/File Name columns.")            continue        spectra = filelist[            (filelist[type_col].astype(str).str.strip() == "Spectrum")            & (filelist[name_col].astype(str).str.lower().str.endswith(".fits"))        ]        if spectra.empty:            print(f"[ExoFOP NONE] TIC {tic}: no Spectrum .fits available.")            continue        target_dir = out_root / f"TIC{tic}"        tmp_zip = target_dir / f"TIC{tic}_allfiles.zip"        tmp_extract = target_dir / "tmp_extract"        if tmp_extract.exists():            shutil.rmtree(tmp_extract, ignore_errors=True)        ok = exofop_download_all_files_zip(tic, tmp_zip)        if not ok:            print(f"[ExoFOP ERROR] TIC {tic}: failed to download zip of files.")            continue        exofop_extract_zip(tmp_zip, tmp_extract)        allowed = set(spectra[name_col].astype(str).tolist())        kept = exofop_keep_only_selected_files(tmp_extract, allowed)        final_dir = target_dir / "Spectrum_fits"        if final_dir.exists():            shutil.rmtree(final_dir, ignore_errors=True)        final_dir.mkdir(parents=True, exist_ok=True)        for f in tmp_extract.rglob("*.fits"):            shutil.move(str(f), str(final_dir / f.name))        shutil.rmtree(tmp_extract, ignore_errors=True)        try:            tmp_zip.unlink()        except OSError:            pass        print(f"[ExoFOP OK] {target_name} --> TIC {tic}: saved {kept} Spectrum .fits in {final_dir}")# ============================================================# --------------------- KOA DOWNLOAD --------------------------# ============================================================# NOTE: this keeps your KOA logic, just wrapped.from pykoa.koa import Koa  # noqa: E402def koa_ensure_dir(p: Path) -> None:    p.mkdir(parents=True, exist_ok=True)def koa_query_to_ipac(instrument: str, target: str, date_start: str, date_end: str, outpath: Path) -> None:    params = {        "instrument": instrument.lower(),        "target": target,        "date": f"{date_start}/{date_end}",    }    Koa.query_criteria(params, str(outpath), overwrite=True, format="ipac")def koa_query_by_radec(instrument: str, ra: float, dec: float, radius_arcsec: float, date_start: str, date_end: str, outpath: Path) -> None:    radius_deg = radius_arcsec / 3600.0    params = {        "instrument": instrument.lower(),        "ra": ra,        "dec": dec,        "radius": radius_deg,        "date": f"{date_start}/{date_end}",    }    Koa.query_criteria(params, str(outpath), overwrite=True, format="ipac")def koa_has_rows(ipac_path: Path) -> bool:    if not ipac_path.exists():        return False    try:        t = Table.read(str(ipac_path), format="ipac")        if len(t) == 0 or "koaid" not in t.colnames:            return False        koaids = [str(x).strip().lower() for x in t["koaid"]]        real = [k for k in koaids if k not in ("", "null", "none")]        return len(real) > 0    except Exception:        return Falsedef koa_download_koaproducts(ipac_path: Path, outdir: Path, *, lev0file: int, lev1file: int, calibfile: int = 0) -> None:    koa_ensure_dir(outdir)    Koa.download(        str(ipac_path),        "ipac",        str(outdir),        lev0file=lev0file,        lev1file=lev1file,        calibfile=calibfile,        calibdir=1,    )def koa_organize_hires_lev1_extracted(outdir: Path) -> None:    src = outdir / "lev1" / "binaryfits"    if not src.exists():        print(f"[HIRES] expected folder not found: {src}")        return    dst = outdir / "lev1" / "extracted"    dst.mkdir(parents=True, exist_ok=True)    flux_dirs = list(src.rglob("flux"))    if not flux_dirs:        print(f"[HIRES] no flux directories found under {src}")        return    fits_files: list[Path] = []    for fd in flux_dirs:        fits_files.extend(fd.rglob("*.fits"))        fits_files.extend(fd.rglob("*.fits.gz"))    fits_files = sorted(set(fits_files))    if not fits_files:        print(f"[HIRES] no FITS files found under flux directories in {src}")        return    kept = 0    for f in fits_files:        stem = f.name        if stem.startswith("HI."):            exposure_id = stem.split("_")[0]        else:            exposure_id = "unknown"        sub = dst / exposure_id        sub.mkdir(parents=True, exist_ok=True)        ccd = f.parent.parent.name        out_name = f"{ccd}__{stem}"        shutil.copy2(f, sub / out_name)        kept += 1    print(f"[HIRES] copied {kept} extracted spectrum FITS file(s) from flux/ into {dst}")def koa_choose_target_name(row: pd.Series) -> str:    hostname = str(row.get("hostname", "")).strip()    pl_name = str(row.get("pl_name", "")).strip()    return hostname if hostname else pl_namedef run_koa_download(    targets_csv: str,    data_root: Path,    meta_root: Path,    cookie: str,    instruments_pipe: str,    date_start: str,    date_end: str,    radius_arcsec: float,    max_targets: int,):    if cookie:        koa_ensure_dir(Path(cookie).parent)        Koa.login(cookie)    df = pd.read_csv(targets_csv)    if max_targets > 0:        df = df.head(max_targets)    data_root = Path(data_root)    meta_root = Path(meta_root)    koa_ensure_dir(data_root)    koa_ensure_dir(meta_root)    requested = [x.strip().upper() for x in str(instruments_pipe).split("|") if x.strip()]    allowed = {"HIRES", "ESI", "KPF"}    instruments = [i for i in requested if i in allowed]    if not instruments:        raise ValueError(f"No recognized instruments in --koa-instruments='{instruments_pipe}'")    for _, row in tqdm(df.iterrows(), total=len(df), desc="KOA Targets"):        target = koa_choose_target_name(row)        if not target:            continue        safe_name = target.replace(" ", "_").replace("/", "_")        for inst in instruments:            inst_lower = inst.lower()            meta_path = meta_root / inst / f"{safe_name}_{date_start}_{date_end}.tbl"            koa_ensure_dir(meta_path.parent)            print(f"\n[KOA {inst}] querying {target} ({date_start} → {date_end})")            try:                koa_query_to_ipac(inst_lower, target, date_start, date_end, meta_path)            except Exception as e:                print(f"[KOA {inst}] name query failed for {target}: {e}")            if not koa_has_rows(meta_path):                try:                    ra = float(row["ra"])                    dec = float(row["dec"])                    print(f"[KOA {inst}] no name match; retrying with RA/Dec ({ra}, {dec}), r={radius_arcsec} arcsec")                    koa_query_by_radec(inst_lower, ra, dec, radius_arcsec, date_start, date_end, meta_path)                except Exception as e:                    print(f"[KOA {inst}] RA/Dec query failed for {target}: {e}")            if not koa_has_rows(meta_path):                print(f"[KOA {inst}] no rows returned for {target} (name + RA/Dec)")                continue            outdir = data_root / inst / safe_name            if inst == "HIRES":                if (outdir / "lev1" / "binaryfits").exists():                    print(f"[KOA {inst}] lev1 already exists, skipping download → {outdir}")                else:                    print(f"[KOA {inst}] downloading EXTRACTED spectra (Level 1) ONLY → {outdir}")                    koa_download_koaproducts(meta_path, outdir, lev0file=0, lev1file=1, calibfile=0)                koa_organize_hires_lev1_extracted(outdir)            elif inst == "ESI":                print(f"[KOA {inst}] downloading RAW (Level 0) → {outdir}")                koa_download_koaproducts(meta_path, outdir, lev0file=1, lev1file=0, calibfile=0)            elif inst == "KPF":                print(f"[KOA {inst}] attempting Level 1 download (if available) → {outdir}")                koa_download_koaproducts(meta_path, outdir, lev0file=0, lev1file=1, calibfile=0)    print("\n[KOA] Done.")# ============================================================# --------------------- SOPHIE DOWNLOAD -----------------------# ============================================================SOPHIE_BASE_URL = "http://atlas.obs-hp.fr/sophie/sophie.cgi"SOPHIE_WANTED_FIBERS = {"sky", "wave"}  # lowercasedef sophie_read_targets(csv_path: str):    targets = []    with open(csv_path, "r", encoding="utf-8", newline="") as f:        for row in csv.DictReader(f):            name = (row.get("archive_name") or "").strip()            if name:                targets.append(name)    return targetsdef sophie_extract_seq_fiber_from_htab(html_text: str):    row_blocks = re.findall(r"<tr[^>]*>.*?</tr>", html_text, flags=re.DOTALL | re.IGNORECASE)    out = []    for row in row_blocks:        m_seq = re.search(r"<td[^>]*>\s*(\d{3,})\s*</td>", row, flags=re.IGNORECASE)        m_fib = re.search(r"<td[^>]*>\s*(SKY|WAVE)\s*</td>", row, flags=re.IGNORECASE)        if not (m_seq and m_fib):            continue        seq = m_seq.group(1)        fiber = m_fib.group(1).lower()        if fiber in SOPHIE_WANTED_FIBERS:            out.append((seq, fiber))    seen = set()    dedup = []    for item in out:        if item not in seen:            seen.add(item)            dedup.append(item)    return dedupdef sophie_download_spectrum(session: requests.Session, seq: str, fiber: str, target_dir: Path):    params = {        "n": "sophie",        "a": "mime:application/fits",        "o": f"sophie:[{fiber},{seq}]",    }    fname = f"{seq}_{fiber}.fits"    outpath = target_dir / fname    if outpath.exists():        print(f"  Skipping {fname}")        return    print(f"  Downloading {fname}")    with session.get(SOPHIE_BASE_URL, params=params, stream=True, timeout=180) as r:        r.raise_for_status()        with outpath.open("wb") as f:            for chunk in r.iter_content(1024 * 1024):                if chunk:                    f.write(chunk)def run_sophie_download(matched_csv: str, outdir: Path, max_targets: int):    outdir.mkdir(parents=True, exist_ok=True)    targets = sophie_read_targets(matched_csv)    if max_targets > 0:        targets = targets[:max_targets]    print(f"[SOPHIE] Targets to query: {len(targets)}")    session = requests.Session()    session.headers.update(        {            "User-Agent": "Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7) Safari/605.1.15",            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",        }    )    for t in targets:        print(f"\n[SOPHIE] === {t} ===")        safe_name = re.sub(r"[^\w\-\+\.]", "_", t)        tdir = outdir / safe_name        tdir.mkdir(parents=True, exist_ok=True)        params = {"n": "sophie", "c": "o", "a": "htab", "o": t}        try:            print("  Querying archive...")            r = session.get(SOPHIE_BASE_URL, params=params, timeout=90)            r.raise_for_status()            observations = sophie_extract_seq_fiber_from_htab(r.text)            print(f"  Found {len(observations)} SKY/WAVE rows")            if not observations:                continue            for seq, fiber in observations:                try:                    sophie_download_spectrum(session, seq, fiber, tdir)                except Exception as e:                    print(f"    FAILED {seq}_{fiber}: {e}")                time.sleep(0.5)        except Exception as e:            print(f"  FAILED to process {t}: {e}")        time.sleep(2)# ============================================================# ------------- ORGANIZE EVERYTHING TO ONE TREE ---------------# ============================================================def safe_name(x: str) -> str:    for ch in ['/', '\\', ':', '*', '?', '"', '<', '>', '|', ' ']:        x = x.replace(ch, '_')    return xdef extract_target_from_path(path: Path) -> Optional[str]:    parts = path.parts    # ---------- KOA HIRES ----------    # data/koa/HIRES/<TARGET>/lev1/extracted/...    if "koa" in parts and "HIRES" in parts:        try:            i = parts.index("HIRES")            return parts[i + 1]        except Exception:            return None    # ---------- KOA other instruments ----------    # data/koa/ESI/<TARGET>/...    if "koa" in parts:        for inst in ("HIRES", "ESI", "KPF"):            if inst in parts:                try:                    i = parts.index(inst)                    return parts[i + 1]                except Exception:                    pass    # ---------- EXOFOP ----------    # data/exofop_spectra/TIC118327550/Spectrum_fits/file.fits    if "exofop_spectra" in parts:        try:            i = parts.index("exofop_spectra")            return parts[i + 1]        except Exception:            return None    # ---------- ESO ----------    # data/raw/ESO/<TARGET>/...    if "raw" in parts and "ESO" in parts:        try:            i = parts.index("ESO")            return parts[i + 1]        except Exception:            return None    # ---------- SOPHIE ----------    # data/sophie/<TARGET>/...    if "sophie" in parts:        try:            i = parts.index("sophie")            return parts[i + 1]        except Exception:            return None    return Nonedef run_organize_all_fits(data_root: Path, output_root: Path) -> tuple[int, int]:    output_root.mkdir(parents=True, exist_ok=True)    copied = 0    checked = 0    print("\n[ORGANIZE] Scanning filesystem once...")    for file_path in data_root.rglob("*"):        if not file_path.is_file():            continue        if not file_path.name.lower().endswith(FITS_EXTENSIONS):            continue        # don't copy from output folder        if output_root.resolve() in file_path.resolve().parents:            continue        checked += 1        target = extract_target_from_path(file_path)        if target is None:            continue        target_folder = output_root / safe_name(target)        target_folder.mkdir(parents=True, exist_ok=True)        dest = target_folder / file_path.name        # prevent overwrite collisions by renaming if needed        if dest.exists():            stem = dest.stem            suf = dest.suffix            k = 2            while dest.exists():                dest = target_folder / f"{stem}__dup{k}{suf}"                k += 1        try:            shutil.copy2(file_path, dest)            copied += 1        except Exception as e:            print("[ORGANIZE] Error copying:", e)    print("\n[ORGANIZE] DONE")    print("[ORGANIZE] FITS-ish files found:", checked)    print("[ORGANIZE] FITS-ish files copied:", copied)    print("[ORGANIZE] Output location:", output_root.resolve())    return checked, copied# ============================================================# ---------------- MASTER CSV (YOUR SNR CODE) -----------------# ============================================================warnings.filterwarnings("ignore", message=".*header keyword is invalid.*")warnings.filterwarnings("ignore", module="astropy.io.fits.card")warnings.simplefilter("ignore", VerifyWarning)def normalize_name(s: str) -> str:    s = str(s).lower().strip()    s = s.replace("’", "").replace("'", "")    s = re.sub(r"[\s\-_]+", "", s)    return sdef clean_obj_name(s: str) -> str:    s = str(s).strip()    s = s.replace("TOI ", "TOI-").replace("TIC ", "TIC")    s = re.sub(r"\s+", " ", s)    return sdef build_target_lookup(targets_df: pd.DataFrame) -> dict:    lookup = {}    cols = {c.lower(): c for c in targets_df.columns}    ra_col = cols.get("ra")    dec_col = cols.get("dec")    hostname_col = cols.get("hostname")    plname_col = cols.get("pl_name")    for _, row in targets_df.iterrows():        ra = float(row[ra_col]) if ra_col and pd.notna(row.get(ra_col, np.nan)) else np.nan        dec = float(row[dec_col]) if dec_col and pd.notna(row.get(dec_col, np.nan)) else np.nan        names = []        if hostname_col and pd.notna(row.get(hostname_col, np.nan)):            names.append(str(row[hostname_col]))        if plname_col and pd.notna(row.get(plname_col, np.nan)):            names.append(str(row[plname_col]))        for name in names:            key = normalize_name(name)            if key:                lookup[key] = (name, ra, dec)    return lookupdef infer_target_from_text(text: str, lookup: dict) -> tuple[str, float, float]:    tnorm = normalize_name(text)    best = None    best_len = -1    for key, (name, ra, dec) in lookup.items():        if key and key in tnorm and len(key) > best_len:            best = (name, ra, dec)            best_len = len(key)    if best is None:        return ("UNKNOWN", np.nan, np.nan)    return bestdef infer_target_from_path(fp: str, lookup: dict) -> tuple[str, float, float]:    p = Path(fp)    candidates = []    for k in [p.parent.name, p.parent.parent.name, p.parent.parent.parent.name]:        if k and k not in candidates:            candidates.append(k)    for cand in candidates:        host, ra, dec = infer_target_from_text(cand, lookup)        if host != "UNKNOWN":            return host, ra, dec    if candidates:        return candidates[0], np.nan, np.nan    return ("UNKNOWN", np.nan, np.nan)def keep_koa_file(fp: str) -> bool:    p = fp.lower()    bad = [        "arc", "arcids", "bias", "dark", "flat", "trace", "lamp", "thar", "calib",        "focus", "pin", "engineering"    ]    if any(b in p for b in bad):        return False    if "/anc/" in p or "/cal/" in p:        return False    return Truedef file_size_ok(fp: str) -> bool:    try:        return Path(fp).stat().st_size > 10_000    except Exception:        return Falsedef get_header_str(hdr, *keys, default="UNKNOWN"):    for k in keys:        try:            v = hdr.get(k, None)            if v is None:                continue            s = str(v).strip()            if s:                return s        except Exception:            pass    return defaultdef pick_col_contains(names, keys):    names_u = [str(n).upper() for n in names]    for key in keys:        ku = key.upper()        for orig, up in zip(names, names_u):            if ku in up:                return orig    return Nonedef multispec_specs_from_header(hdr) -> dict[int, str]:    wat_keys = [k for k in hdr.keys() if str(k).upper().startswith("WAT2_")]    if not wat_keys:        return {}    wat_keys = sorted(wat_keys, key=lambda k: int(str(k).split("_")[1]))    chunks = [str(hdr[k]) for k in wat_keys]    specs: dict[int, str] = {}    collecting = False    current_idx = None    buf = []    start_pat = re.compile(r"spec\s*(\d+)\s*=\s*\"")    for chunk in chunks:        s = chunk.replace("\n", " ")        pos = 0        while pos < len(s):            if not collecting:                m = start_pat.search(s, pos)                if not m:                    break                current_idx = int(m.group(1))                collecting = True                buf = []                pos = m.end()            else:                q = s.find('"', pos)                if q == -1:                    buf.append(s[pos:])                    break                buf.append(s[pos:q])                specs[current_idx] = "".join(buf).strip()                collecting = False                current_idx = None                buf = []                pos = q + 1    return specsdef _wavelength_from_multispec_spec(spec_str: str):    nums = [float(x) for x in re.findall(r"[+-]?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?", spec_str)]    if len(nums) < 6:        return None    try:        dtype = int(round(nums[2]))        w1 = float(nums[3])        dw = float(nums[4])        n = int(round(nums[5]))    except Exception:        return None    if n <= 10:        return None    pix = np.arange(n, dtype=float)    if dtype == 1:        wave = 10 ** (w1 + dw * pix)    else:        wave = w1 + dw * pix    if np.nanmean(np.diff(wave) > 0) < 0.5:        wave = wave[::-1]    if not np.isfinite(wave).all():        return None    return wavedef wave_flux_from_multispec_primary(primary_hdu):    data = np.asarray(primary_hdu.data)    hdr = primary_hdu.header    if data is None or data.ndim != 2:        return []    n_orders, _ = data.shape    specs = multispec_specs_from_header(hdr)    if not specs:        return []    orders = []    for order_idx in range(1, n_orders + 1):        spec_str = specs.get(order_idx, None)        if not spec_str:            continue        wave = _wavelength_from_multispec_spec(spec_str)        if wave is None:            continue        flux = np.array(data[order_idx - 1, :], dtype=float)        n = min(wave.size, flux.size)        if n > 50:            orders.append((wave[:n], flux[:n]))    return ordersdef linear_wavelength_from_header(hdr, npts: int):    crval = hdr.get("CRVAL1", None)    cdelt = hdr.get("CDELT1", hdr.get("CD1_1", None))    crpix = hdr.get("CRPIX1", 1.0)    if crval is None or cdelt is None:        return None    try:        crval = float(crval)        cdelt = float(cdelt)        crpix = float(crpix)    except Exception:        return None    i = np.arange(npts, dtype=float)    lam = crval + (i + 1.0 - crpix) * cdelt    return lamdef find_wave_flux_from_primary_matrix(data2d: np.ndarray):    d = np.array(data2d, dtype=float)    if d.ndim != 2:        return None, None    n_tracks, _ = d.shape    if n_tracks < 2 or n_tracks > 30:        return None, None    wave_scores = []    for i in range(n_tracks):        v = d[i]        m = np.isfinite(v)        if m.sum() < 50:            wave_scores.append((-1, i))            continue        vv = v[m]        inc = np.mean(np.diff(vv) > 0)        vmin, vmax = float(np.nanmin(vv)), float(np.nanmax(vv))        plausible = (100 < vmin < 20000) and (100 < vmax < 20000) and (vmax > vmin)        score = inc if plausible else -1        wave_scores.append((score, i))    wave_scores.sort(reverse=True)    best_score, wave_i = wave_scores[0]    if best_score < 0.90:        return None, None    wave = d[wave_i]    flux_i = None    best_flux_score = -1    for i in range(n_tracks):        if i == wave_i:            continue        v = d[i]        m = np.isfinite(v)        if m.sum() < 50:            continue        vv = v[m]        inc = np.mean(np.diff(vv) > 0)        score = (1 - inc) * np.nanpercentile(np.abs(vv), 90)        if score > best_flux_score:            best_flux_score = score            flux_i = i    if flux_i is None:        return None, None    flux = d[flux_i]    n = min(wave.size, flux.size)    if n <= 50:        return None, None    return wave[:n], flux[:n]def find_flux_wave_in_hdul(hdul):    for hdu in hdul:        if isinstance(hdu, (fits.BinTableHDU, fits.TableHDU)) and getattr(hdu, "columns", None) is not None:            names = list(hdu.columns.names or [])            if not names:                continue            wcol = pick_col_contains(names, ["WAVE", "WAVEL", "LAMBDA", "LAM", "WL"])            fcol = pick_col_contains(names, ["FLUX", "SUM_FLUX", "SPEC", "SPECT", "COUNTS", "INTENS"])            if wcol and fcol:                wave = np.array(hdu.data[wcol], dtype=float).ravel()                flux = np.array(hdu.data[fcol], dtype=float).ravel()                n = min(wave.size, flux.size)                if n > 50:                    return wave[:n], flux[:n]    for hdu in hdul:        data = getattr(hdu, "data", None)        if isinstance(data, np.ndarray) and data.ndim == 2 and 2 <= data.shape[0] <= 30:            wave, flux = find_wave_flux_from_primary_matrix(data)            if wave is not None and flux is not None:                return wave, flux    for hdu in hdul:        data = getattr(hdu, "data", None)        hdr = getattr(hdu, "header", None)        if data is None or hdr is None:            continue        if isinstance(data, np.ndarray) and data.ndim == 1 and data.size > 50:            wave = linear_wavelength_from_header(hdr, data.size)            if wave is not None:                return wave, np.array(data, dtype=float)            return None, np.array(data, dtype=float)    for hdu in hdul:        data = getattr(hdu, "data", None)        if isinstance(data, np.ndarray) and data.ndim == 2 and data.size > 200:            return None, np.array(data, dtype=float)    return None, Nonedef robust_snr(flux: np.ndarray) -> float:    f = np.array(flux, dtype=float).ravel()    f = f[np.isfinite(f)]    if f.size < 50:        return np.nan    signal = np.nanmedian(np.abs(f))    if not np.isfinite(signal) or signal == 0:        return np.nan    df = np.diff(f)    if df.size < 20:        return np.nan    mad = np.median(np.abs(df - np.median(df)))    sigma = 1.4826 * mad / np.sqrt(2.0)    if not np.isfinite(sigma) or sigma <= 0:        return np.nan    return float(signal / sigma)def snr_in_window(wave, flux, wmin, wmax):    if wave is None:        return np.nan    w = np.array(wave, dtype=float).ravel()    f = np.array(flux, dtype=float).ravel()    m = np.isfinite(w) & np.isfinite(f) & (w >= wmin) & (w <= wmax)    if m.sum() < 30:        return np.nan    return robust_snr(f[m])def compute_snrs_and_range_from_fits(fp: str):    with fits.open(fp, memmap=False) as hdul:        h0 = hdul[0]        hdr0 = h0.header        is_multispec = ("WAT0_001" in hdr0) or any(str(k).upper().startswith("WAT2_") for k in hdr0.keys())        if is_multispec and isinstance(h0.data, np.ndarray) and h0.data.ndim == 2:            orders = wave_flux_from_multispec_primary(h0)            if orders:                wmins = []                wmaxs = []                order_snrs = []                for w, f in orders:                    wmins.append(float(np.nanmin(w)))                    wmaxs.append(float(np.nanmax(w)))                    s = robust_snr(f)                    if np.isfinite(s):                        order_snrs.append(s)                wlow = float(np.nanmin(wmins)) if wmins else np.nan                whigh = float(np.nanmax(wmaxs)) if wmaxs else np.nan                if order_snrs:                    order_snrs = np.sort(np.array(order_snrs))                    snr_gen = float(np.median(order_snrs[len(order_snrs) // 2 :]))                else:                    snr_gen = np.nan                def best_snr_in_window(wmin, wmax):                    vals = []                    for w, f in orders:                        s = snr_in_window(w, f, wmin, wmax)                        if np.isfinite(s):                            vals.append(s)                    return float(np.nanmax(vals)) if vals else np.nan                snr_li = best_snr_in_window(6707.0, 6711.0)                snr_ha = best_snr_in_window(6560.0, 6566.0)                snr_ca = best_snr_in_window(3929.0, 3972.0)                return snr_gen, snr_li, snr_ha, snr_ca, wlow, whigh        wave, flux = find_flux_wave_in_hdul(hdul)        wlow = np.nan        whigh = np.nan        if wave is not None:            ww = np.array(wave, dtype=float).ravel()            ww = ww[np.isfinite(ww)]            if ww.size > 10:                wlow = float(np.nanmin(ww))                whigh = float(np.nanmax(ww))        if flux is None:            return np.nan, np.nan, np.nan, np.nan, wlow, whigh        if isinstance(flux, np.ndarray) and flux.ndim == 2:            order_snrs = []            for i in range(flux.shape[0]):                s = robust_snr(flux[i, :])                if np.isfinite(s):                    order_snrs.append(s)            if order_snrs:                order_snrs = np.sort(np.array(order_snrs))                snr_gen = float(np.median(order_snrs[len(order_snrs) // 2 :]))            else:                snr_gen = np.nan            return snr_gen, np.nan, np.nan, np.nan, wlow, whigh        snr_gen = robust_snr(flux)        snr_li = snr_in_window(wave, flux, 6707.0, 6711.0)        snr_ha = snr_in_window(wave, flux, 6560.0, 6566.0)        snr_ca = snr_in_window(wave, flux, 3929.0, 3972.0)        return snr_gen, snr_li, snr_ha, snr_ca, wlow, whighdef build_master_csv(    targets_csv: str,    glob_pattern: str,    out_csv: str,):    targets = pd.read_csv(targets_csv)    lookup = build_target_lookup(targets)    files = sorted(set(glob.glob(glob_pattern, recursive=True)))    files = [f for f in files if keep_koa_file(f)]    files = [f for f in files if file_size_ok(f)]    print("\n[CSV] Found organized spectra files (filtered):", len(files))    rows = []    for fp in files:        try:            with fits.open(fp, memmap=False) as hdul:                hdr0 = hdul[0].header                instrument = get_header_str(hdr0, "INSTRUME", "TELESCOP", default="UNKNOWN")                obj = get_header_str(hdr0, "OBJECT", "TARGNAME", "TARGET", default="UNKNOWN")            snr_gen, snr_li, snr_ha, snr_ca, wlow, whigh = compute_snrs_and_range_from_fits(fp)            host, ra, dec = infer_target_from_text(clean_obj_name(obj), lookup)            if host == "UNKNOWN":                host, ra, dec = infer_target_from_text(fp, lookup)            if host == "UNKNOWN":                host, ra, dec = infer_target_from_path(fp, lookup)            rows.append(                {                    "Filename": fp,                    "Target": host,                    "RA": ra,                    "Dec": dec,                    "instrument": instrument,                    "SNR_General": snr_gen,                    "SNR-Li": snr_li,                    "SNR_Ha": snr_ha,                    "SNR_Ca": snr_ca,                    "wavelength-low": wlow,                    "wavelength-high": whigh,                }            )        except Exception:            rows.append(                {                    "Filename": fp,                    "Target": "UNKNOWN",                    "RA": np.nan,                    "Dec": np.nan,                    "instrument": "UNKNOWN",                    "SNR_General": np.nan,                    "SNR-Li": np.nan,                    "SNR_Ha": np.nan,                    "SNR_Ca": np.nan,                    "wavelength-low": np.nan,                    "wavelength-high": np.nan,                }            )    df = pd.DataFrame(rows)    df = df[        [            "Filename",            "Target",            "RA",            "Dec",            "instrument",            "SNR_General",            "SNR-Li",            "SNR_Ha",            "SNR_Ca",            "wavelength-low",            "wavelength-high",        ]    ]    df.to_csv(out_csv, index=False)    print(f"[CSV] Wrote {out_csv} with {len(df)} rows")    n_with_snr = int(df["SNR_General"].notna().sum())    print(f"[CSV] SNR present in {n_with_snr}/{len(df)} rows")# ============================================================# --------------------------- MAIN ----------------------------# ============================================================def main():    ap = argparse.ArgumentParser()    ap.add_argument("--targets-csv", default=DEFAULT_TARGETS_CSV)    ap.add_argument("--eso-csv", default=DEFAULT_ESO_TARGETS_CSV)    ap.add_argument("--matched-csv", default=DEFAULT_MATCHED_CSV)    ap.add_argument("--max-targets", type=int, default=0, help="If >0: limit target count for EACH archive step")    ap.add_argument("--max-files-per-target", type=int, default=10, help="ESO per-target file cap")    ap.add_argument("--eso-radius-arcmin", type=float, default=5.0)    ap.add_argument("--eso-timeout-sec", type=int, default=25)    ap.add_argument("--koa-cookie", default="", help="Optional KOA cookie path for proprietary access")    ap.add_argument("--koa-instruments", default="HIRES", help="HIRES|ESI|KPF")    ap.add_argument("--koa-date-start", default="1994-01-01")    ap.add_argument("--koa-date-end", default="2026-12-31")    ap.add_argument("--koa-radius-arcsec", type=float, default=30.0)    ap.add_argument("--skip-eso", action="store_true")    ap.add_argument("--skip-exofop", action="store_true")    ap.add_argument("--skip-koa", action="store_true")    ap.add_argument("--skip-sophie", action="store_true")    ap.add_argument("--skip-organize", action="store_true")    ap.add_argument("--skip-csv", action="store_true")    ap.add_argument("--out-csv", default="Carmen_master_spectra.csv")    args = ap.parse_args()    # 1) Downloads    if not args.skip_eso:        run_eso_download(            csv_file=args.eso_csv,            outdir=ESO_OUTDIR,            max_targets=args.max_targets,            max_files_per_target=args.max_files_per_target,            radius_arcmin=args.eso_radius_arcmin,            timeout_sec=args.eso_timeout_sec,        )    if not args.skip_exofop:        run_exofop_download(            target_list_csv=args.targets_csv,            out_root=EXOFOP_DIR,            max_targets=args.max_targets,        )    if not args.skip_koa:        run_koa_download(            targets_csv=args.targets_csv,            data_root=KOA_DATA_ROOT,            meta_root=KOA_META_ROOT,            cookie=args.koa_cookie,            instruments_pipe=args.koa_instruments,            date_start=args.koa_date_start,            date_end=args.koa_date_end,            radius_arcsec=args.koa_radius_arcsec,            max_targets=args.max_targets,        )    if not args.skip_sophie:        run_sophie_download(            matched_csv=args.matched_csv,            outdir=SOPHIE_OUTDIR,            max_targets=args.max_targets,        )    # 2) Organize    if not args.skip_organize:        run_organize_all_fits(DATA_DIR, OUT_ORGANIZED)    # 3) CSV    if not args.skip_csv:        glob_pattern = str(OUT_ORGANIZED / "**" / "*.*fits*")        build_master_csv(            targets_csv=args.targets_csv,            glob_pattern=glob_pattern,            out_csv=args.out_csv,        )    print("\nAll done.")if __name__ == "__main__":    main()